/** Tiny neutral blur used as Next/Image placeholder across the site */
export const BLUR_DATA_URL =
  "data:image/jpeg;base64,";

/** Hero / full-bleed — must match next.config images.qualities */
export const IMAGE_QUALITY_HERO = 85;
/** Cards / grids */
export const IMAGE_QUALITY_CARD = 75;
/** Thumbnails */
export const IMAGE_QUALITY_THUMB = 65;

/**
 * Local /public assets are already optimized files.
 * Skip the Next.js image optimizer so they load instantly (no /_next/image hop).
 */
export const LOCAL_IMAGE_PROPS = {
  unoptimized: true,
} as const;
